function check(lat) {
  if (!(lat >= -90 && lat <= 90)) throw new Error('latitude ' + lat + ' not in [-90, 90]');
}

// The midpoint of the geodesic between two points, on a sphere.
export function geodesicMidpoint(lon1, lat1, lon2, lat2) {
  check(lat1);
  check(lat2);
  const r = Math.PI / 180;
  const bx = Math.cos(lat2 * r) * Math.cos((lon2 - lon1) * r);
  const by = Math.cos(lat2 * r) * Math.sin((lon2 - lon1) * r);
  const lat = Math.atan2(Math.sin(lat1 * r) + Math.sin(lat2 * r), Math.hypot(Math.cos(lat1 * r) + bx, by));
  const lon = lon1 * r + Math.atan2(by, Math.cos(lat1 * r) + bx);
  return { lon: lon / r, lat: lat / r };
}

