import { geodesicMidpoint } from './geodesy.js';

// Measure > Centre Point of a line feature.
export function lineCentre(layer, feature) {
  const coords = feature.geometry.coordinates;
  const [lon1, lat1] = coords[0];
  const [lon2, lat2] = coords[coords.length - 1];
  return geodesicMidpoint(lon1, lat1, lon2, lat2);
}
